from errors import StorageError
from models import Priority, Task
assert JsonStorage("missing.json").load() == [], "A missing file means no tasks yet: load() should return []."
for name in ["tasks.json", "old.json"]:
    try:
        JsonStorage(name).load()
    except StorageError as err:
        assert name in str(err), "Name the file in the StorageError message, so the user knows which file is broken. It said: " + str(err)
    except Exception as err:
        raise AssertionError("Loading the broken " + name + " raised " + type(err).__name__ + ". Catch it and raise StorageError instead.")
